]??'')?></td><td>KES <?=number_format((float)$x['unit_cost'],2)?></td><td>KES <?=number_format((float)$x['line_total'],2)?></td></tr><?php endforeach;?></tbody></table><div class="total"><span>GRN Total</span><span>KES <?=number_format((float)$gr['total_amount'],2)?></span></div><?php if($gr['notes']):?><p style="margin-top:30px"><strong>Notes:</strong><br><?=nl2br(e($gr['notes']))?></p><?php endif;?></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>